import openpyxl
wb = openpyxl.load_workbook('/app/department_expenses.xlsx')
ws = wb.active
print('Sheet name:', ws.title)
print('Dimensions:', ws.dimensions)
print()
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    vals = []
    for cell in row:
        if cell.value is not None:
            if hasattr(cell.value, '__float__'):
                vals.append(f'{cell.value:.2f}')
            else:
                vals.append(str(cell.value))
        else:
            vals.append('')
    print(f'Row {row[0].row}: {vals}')
"
